# Reviewed under AGENTS.md
"""Semantic version ordering helpers."""

from __future__ import annotations

__all__ = ['sort_versions']


def _identifier_key(identifier: str) -> tuple[int, int | str]:
    """Return a comparison key for one pre-release identifier."""
    if identifier.isascii() and identifier.isdigit():
        return (0, int(identifier))
    return (1, identifier)


def _precedence(version: str) -> tuple[int, int, int, int, tuple[tuple[int, int | str], ...]]:
    """Return a key implementing SemVer 2.0.0 precedence."""
    version_without_build = version.partition('+')[0]
    core, separator, prerelease = version_without_build.partition('-')
    major, minor, patch = (int(part) for part in core.split('.'))

    if not separator:
        # A release sorts after any pre-release of the same core version.
        return (major, minor, patch, 1, ())

    identifiers = tuple(_identifier_key(identifier) for identifier in prerelease.split('.'))
    return (major, minor, patch, 0, identifiers)


def sort_versions(vs: list[str]) -> list[str]:
    """Sort semantic version strings by precedence, lowest first.

    Build metadata is ignored for ordering, and versions with equal precedence
    retain their original relative order.
    """
    return sorted(vs, key=_precedence)
